TLM.f("Tempora/Quadp3-3",{"officium":"Feria IV Cinerum","rule":["no Gloria","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;","Super populum","Prelude","omit incipit"],"ruleInherited":["no Gloria","Credo","Prefatio=Trinitate","Suffr=Maria2;Sanctorum,Ecclesiæ;;"],"fallback":"Tempora/Quadp3-0","from":{"GradualeF":"Tempora/Quadp3-0"},"sections":{"Introitus":[{"k":"ref","la":"Sap 11:24 11:25; 11:27"},{"k":"text","la":"Miseréris ómnium, Dómine, et nihil odísti eórum quæ fecísti, dissímulans peccáta hóminum propter pæniténtiam et parcens illis: quia tu es Dóminus, Deus noster"},{"k":"ref","la":"Ps 56:2"},{"k":"text","la":"Miserére mei, Deus, miserére mei: quóniam in te confídit ánima mea."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Miseréris ómnium, Dómine, et nihil odísti eórum quæ fecísti, dissímulans peccáta hóminum propter pæniténtiam et parcens illis: quia tu es Dóminus, Deus noster"}],"Oratio":[{"k":"text","la":"Præsta, Dómine, fidélibus tuis: ut jejuniórum veneránda sollémnia, et cóngrua pietáte suscípiant, et secúra devotióne percúrrant."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Joélis Prophétæ"},{"k":"ref","la":"Joël 2:12-19"},{"k":"text","la":"Hæc dicit Dóminus: Convertímini ad me in toto corde vestro, in jejúnio, et in fletu, et in planctu. Et scíndite corda vestra, et non vestiménta vestra, et convertímini ad Dóminum, Deum vestrum: quia benígnus et miséricors est, pátiens, et multæ misericórdiæ, et præstábilis super malítia. Quis scit, si convertátur, et ignóscat, et relínquat post se benedictiónem, sacrifícium et libámen Dómino, Deo vestro? Cánite tuba in Sion, sanctificáte jejúnium, vocáte coetum, congregáte pópulum, sanctificáte ecclésiam, coadunáte senes, congregáte parvulos et sugéntes úbera: egrediátur sponsus de cubíli suo, et sponsa de thálamo suo. Inter vestíbulum et altare plorábunt sacerdótes minístri Dómini, et dicent: Parce, Dómine, parce pópulo tuo: et ne des hereditátem tuam in oppróbrium, ut dominéntur eis natiónes. Quare dicunt in pópulis: Ubi est Deus eórum? Zelátus est Dóminus terram suam, et pepércit pópulo suo. Et respóndit Dóminus, et dixit populo suo: Ecce, ego mittam vobis fruméntum et vinum et óleum, et replebímini eis: et non dabo vos ultra oppróbrium in géntibus: dicit Dóminus omnípotens."}],"Graduale":[{"k":"ref","la":"Ps 56:2; 56:4"},{"k":"text","la":"Miserére mei, Deus, miserére mei: quóniam in te confídit ánima mea."},{"k":"text","la":"Misit de coelo, et liberávit me, dedit in oppróbrium conculcántes me.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis."},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrarum antiquarum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, libera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 76:15; 76:16"},{"k":"text","la":"Tu es Deus qui facis mirabília solus: notam fecísti in géntibus virtútem tuam."},{"k":"text","la":"Liberásti in bráchio tuo pópulum tuum, fílios Israël et Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 6:16-21"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum jejunátis, nolíte fíeri, sicut hypócritæ, tristes. Extérminant enim fácies suas, ut appáreant homínibus jejunántes. Amen, dico vobis, quia recepérunt mercédem suam. Tu autem, cum jejúnas, unge caput tuum, et fáciem tuam lava, ne videáris homínibus jejúnans, sed Patri tuo, qui est in abscóndito: et Pater tuus, qui videt in abscóndito, reddet tibi. Nolíte thesaurizáre vobis thesáuros in terra: ubi ærúgo et tínea demolítur: et ubi fures effódiunt et furántur. Thesaurizáte autem vobis thesáuros in coelo: ubi neque ærúgo neque tínea demolítur; et ubi fures non effódiunt nec furántur. Ubi enim est thesáurus tuus, ibi est et cor tuum."}],"Offertorium":[{"k":"ref","la":"Ps 29:2-3"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me: Dómine, clamávi ad te, et sanásti me."}],"Secreta":[{"k":"text","la":"Fac nos, quǽsumus, Dómine, his munéribus offeréndis conveniénter aptári: quibus ipsíus venerábilis sacraménti celebrámus exórdium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 1:2 et 3"},{"k":"text","la":"Qui meditábitur in lege Dómini die ac nocte, dabit fructum suum in témpore suo."}],"Postcommunio":[{"k":"text","la":"Percépta nobis, Dómine, præbeant sacraménta subsídium: ut tibi grata sint nostra jejúnia, et nobis profíciant ad medélam."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Deinde Sacerdos absolute dicit:"},{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"rubric","la":"Et Diaconus, si in officio Diaconatus serviat versus ad populum, junctis manibus, dicit. Alioquin ipse Sacerdos, stans in eodem loco ante librum, et non vertens se ad populum."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"sep"},{"k":"text","la":"Inclinántes se, Dómine, majestáti tuæ, propitiátus inténde: ut, qui divíno múnere sunt refécti, coeléstibus semper nutriántur auxíliis."},{"k":"macro","name":"Per Dominum"}],"Prelude":[{"k":"head","la":"Benedictio cinerum"},{"k":"rubric","la":"Antiphona."},{"k":"ref","la":"Ps 68:17"},{"k":"text","la":"Exáudi nos, Dómine, quóniam benígna est misericórdia tua: secúndum multitúdinem miseratiónum tuárum réspice nos, Dómine."},{"k":"ref","la":"Ps 68:2"},{"k":"text","la":"Salvum me fac, Deus: quóniam intravérunt aquæ usque ad ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Exáudi nos, Dómine, quóniam benígna est misericórdia tua: secúndum multitúdinem miseratiónum tuárum réspice nos, Dómine."},{"k":"sep"},{"k":"rubric","la":"Deinde Sacerdos in cornu Epistolæ, non vertens se ad populum, manibus junctis (quod servatur etiam in orationibus omnium benedictionum quoad manus junctas) dicit:"},{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"},{"k":"text","la":"Orémus."},{"k":"text","la":"Omnípotens sempitérne Deus, parce pæniténtibus, propitiáre supplicántibus: et míttere dignéris sanctum Angelum tuum de coelis, qui bene + dícat et sanctí + ficet hos cíneres, ut sint remédium salúbre ómnibus nomen sanctum tuum humilíter implorántibus, ac semetípsos pro consciéntia delictórum suórum accusántibus, ante conspéctum divínæ cleméntiæ tuæ facínora sua deplorántibus, vel sereníssimam pietátem tuam supplíciter obnixéque flagitántibus: et præsta per invocatiónem sanctíssimi nóminis tui; ut, quicúmque per eos aspérsi fúerint, pro redemptióne peccatórum suórum, córporis sanitátem et ánimæ tutélam percípiant. Per Christum, Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus."},{"k":"text","la":"Deus, qui non mortem, sed pæniténtiam desíderas peccatórum: fragilitátem condiciónis humánæ benigníssime réspice; et hos cíneres, quos, causa proferéndæ humilitátis atque promeréndæ véniæ, capítibus nostris impóni decérnimus, bene + dícere pro tua pietáte dignáre: ut, qui nos cínerem esse, et ob pravitátis nostræ deméritum in púlverem reversúros cognóscimus; peccatórum ómnium véniam, et præmia pæniténtibus repromíssa, misericórditer cónsequi mereámur. Per Christum, Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus."},{"k":"text","la":"Deus, qui humiliatióne flécteris, et satisfactióne placáris: aurem tuæ pietátis inclína précibus nostris; et capítibus servórum tuórum, horum cínerum aspersióne contáctis, effúnde propítius grátiam tuæ benedictiónis: ut eos et spíritu compunctiónis répleas et, quæ juste postuláverint, efficáciter tríbuas; et concéssa perpétuo stabilíta et intácta manére decérnas. Per Christum, Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus."},{"k":"text","la":"Omnípotens sempitérne Deus, qui Ninivítis, in cínere et cilício pæniténtibus, indulgéntiæ tuæ remédia præstitísti: concéde propítius; ut sic eos imitémur hábitu, quaténus véniæ prosequámur obténtu."},{"k":"text","la":"Per Christum, Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"rubric","la":"Postea Celebrans, imposito incenso in thuribulo, ter aspergit cineres aqua benedícta, dicendo Antiphonam Aspérges, sine cantu et sine Psalmo, et ter adolet incenso. Deinde dignior Sacerdos ex Clero accedens ad Altare, imponit cineres Celebranti non genuflexo. Si vero non adsit alius Sacerdos, ipsemet Celebrans, genibus flexis coram Altari, sibi ipsi cineres imponit in capite, nihil dicens, et cantatur statim a choro:"},{"k":"rubric","la":"Antiphona."},{"k":"ref","la":"Joël 2:13"},{"k":"text","la":"Immutémur habitu, in cínere et cilício: jejunémus, et plorémus ante Dóminum: quia multum miséricors est dimíttere peccáta nostra Deus noster."},{"k":"sep"},{"k":"rubric","la":"Alia Antiph."},{"k":"ref","la":"Joël 2:17"},{"k":"text","la":"Inter vestíbulum et altáre plorábunt sacerdótes minístri Dómini, et dicent: Parce, Dómine, parce pópulo tuo: et ne claudas ora canéntium te, Dómine."},{"k":"sep"},{"k":"rubric","la":"Responsorium"},{"k":"ref","la":"Esther 13; Joël 2"},{"k":"text","la":"Emendémus in mélius, quæ ignoránter peccávimus: ne, subito præoccupáti die mortis, quærámus spátium pæniténtiæ, et inveníre non possímus. Atténde, Dómine, et miserére: quia peccávimus tibi."},{"k":"ref","la":"Ps 78:9"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter honórem nóminis tui, Dómine, líbera nos. Atténde, Dómine, et miserére: quia peccávimus tibi."},{"k":"text","la":"Glória Patri, et Fílio, et Spirítui Sancto. Atténde, Dómine, et miserére: quia peccávimus tibi.","mark":"V"},{"k":"rubric","la":"Sacerdos vero, dum cantantur Antiphonæ et Responsorium, detecto capite, primo imponit cineres digniori Sacerdoti, a quo ipse accepit, deinde Ministris paratis, genibus flexis coram Altari, dicens:"},{"k":"ref","la":"Genesis 3:19"},{"k":"text","la":"Memento, homo, quia pulvis es, et in púlverem revertéris."},{"k":"sep"},{"k":"rubric","la":"Postea veniunt alii, primo Clerus per ordinem, deinde populus: et genibus flexis ante Altare, singulatim recipiunt cinerem a Sacerdote, ut dictum est de Ministris. Completa cinerum impositione, Sacerdos dicit:"},{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"},{"k":"text","la":"Orémus."},{"k":"text","la":"Concéde nobis, Dómine, præsídia milítiæ christiánæ sanctis inchoáre jejúniis: ut, contra spiritáles nequítias pugnatúri, continéntiæ muniámur auxíliis. Per Christum, Dóminum nostrum."},{"k":"text","la":"Amen.","mark":"R"}]},"hr":{"0400c86ffd0dc7c1":{"t":"Mudr, 11, 24, 24 et 27, Ps 56, 2\n(Mudr 11, 24, 24 et 27) Svima se smiluješ, Gospodine, i ne mrziš ni jedan svoj stvor. Ne gledaš na grijehe ljudi, ako čine pokoru, i praštaš im, jer si ti Gospodin Bog naš. (Ps. 56, 2) Smiluj mi se, Bože, smiluj mi se. U te se ufa moja duša.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mudr 11, 24, 24 et 27) Svima se smiluješ, Gospodine, i ne mrziš ni jedan svoj stvor. Ne gledaš na grijehe ljudi, ako čine pokoru, i praštaš im, jer si ti Gospodin Bog naš.","v":"sap et → ∅"},"0e3320d369db7580":{"t":"<i>Pomolimo se</i>.\nPodaj, Gospodine, svojim vjernicima da časne svetkovine posta i započnu prikladnom pobožnošću i da ih s postojanom odanošću dovrše.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c9a20f42f462084f":{"t":"Jl 2, 12-19\nČitanje proroka Joela. Ovo govori Gospodin: Obratite se k meni svim svojim srcem u postu, plaču i tuzi. Razderite svoja srca, a ne svoje haljine i obratite se Bogu, svojem Gospodinu, jer je on dobrostiv, milosrdan, ustrpljiv, bogat milosrđem i oprašta zloće. Tko zna, neće li se obratiti i oprostiti, pa će za sobom ostaviti blagoslov za žrtvu i prinos Bogu, vašem Gospodinu. – Trubljom sa Siona oglasite, odredite post, skupite narod, posvetite skup, saberite starce, pozovite djecu i dojenčad. Neka zaručnik iziđe iz svoje sobe i zaručnica iz svoje odaje. Svećenici i Gospodnje sluge neka između žrtvenika i trijema plaču i zazivaju: »Oprosti, Gospodine, oprosti svojemu narodu i ne dopusti da se tvojemu nasljedstvu izruguju i da nad njim vladaju nevjernici! Zašto da bezbošci govore: »Pa gdje je njihov Bog?« Gospodin je revnovao za svoju zemlju i oprostio svojem narodu. I Gospodin je rekao svojem narodu: »Evo, poslat ću vam žita i vina i ulja. Bit ćete siti, a vas samih neću predati nevjernicima da vas sramote«, to tvrdi svemogući Gospodin."},"27c37606e4811373":{"t":"Ps 56, 2 i 4\nSmiluj mi se, Bože, smiluj mi se. U te se ufa moja duša. Poslao je pomoć s neba i spasio me, osramotio je one koji me gaze.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega."},"30e2ce5a59cbd691":{"t":"Mt 2, 16-21\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Reče Isus svojim učenicima: Kad postite, nemojte biti žalosni kao licemjeri koji nagrđuju svoje obraze, da se pokažu pred ljudima kako poste. Zaista vam kažem, da su oni već primili svoju plaću. A kad ti postiš, namaži svoju glavu i operi svoje lice da te ljudi ne vide kako postiš, nego Otac tvoj koji je nevidljiv. I nagradit će te tvoj Otac koji vidi i sakrivene stvari. – Ne skupljajte blaga na zemlji gdje izgriza moljac i rđa, i gdje potkopavaju lopovi. Nego sabirajte blago na nebu, gdje ne izgriza ni rđa ni moljac i gdje lopovi ne potkopavaju ni kradu. Gdje je tvoje blago ondje je i tvoje srce."},"303da7d32e6bd744":{"t":"Ps 29, 2-3\nSlavit ću te, Gospodine, jer si me uzeo k sebi. Nisi dao da neprijatelj slavi pobjedu nada mnom. Gospodine, zavapio sam k tebi i ozdravio si me."},"938c6954ccc4a929":{"t":"Daj, molimo, Gospodine, da se dostojno pripravimo za prinos ovih darova kojima slavimo početak ovoga otajstvenog vremena.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"4274e162bcafafc9":{"t":"Ps 1, 2-3\nTko razmatra danju i noću o Gospodnjem zakonu taj će plod svoj dati u pravo vrijeme."},"2cbc1f6c59bf5267":{"t":"<i>Pomolimo se</i>.\nPrimljena otajstva, Gospodine, neka nam budu u pomoć, da naš post bude drag tebi, nama da posluži za lijek.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"a03dcc841b6a8cf9":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nPogledaj, Gospodine milostivo one koji se prigibaju pred tvojim veličanstvom, da ih okrijepljene božanskim darom uvijek hrani pomoć nebeska.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
